#include <string>
#include <algorithm>

class Solution {
public:
    std::string shortestSuperstring(std::string s1, std::string s2) {
        if (s2.find(s1) != std::string::npos) return s2;
        if (s1.find(s2) != std::string::npos) return s1;

        auto get_overlap = [](const std::string& a, const std::string& b) {
            int max_len = std::min(a.size(), b.size());
            for (int k = max_len; k > 0; --k) {
                if (a.compare(a.size() - k, k, b, 0, k) == 0) return k;
            }
            return 0;
        };

        int o1 = get_overlap(s1, s2);
        std::string c1 = s1 + s2.substr(o1);

        int o2 = get_overlap(s2, s1);
        std::string c2 = s2 + s1.substr(o2);

        if (c1.size() < c2.size()) return c1;
        if (c2.size() < c1.size()) return c2;
        return std::min(c1, c2);
    }
};

class Solution {
    public String shortestSuperstring(String s1, String s2) {
        if (s2.contains(s1)) return s2;
        if (s1.contains(s2)) return s1;

        int o1 = getOverlap(s1, s2);
        String c1 = s1 + s2.substring(o1);

        int o2 = getOverlap(s2, s1);
        String c2 = s2 + s1.substring(o2);

        if (c1.length() < c2.length()) return c1;
        if (c2.length() < c1.length()) return c2;
        return c1.compareTo(c2) <= 0 ? c1 : c2;
    }

    private int getOverlap(String a, String b) {
        int maxLen = Math.min(a.length(), b.length());
        for (int k = maxLen; k > 0; k--) {
            if (a.endsWith(b.substring(0, k))) return k;
        }
        return 0;
    }
}

