var shortestSuperstring = function(s1, s2) {
    if (s2.includes(s1)) return s2;
    if (s1.includes(s2)) return s1;

    const getOverlap = (a, b) => {
        const maxLen = Math.min(a.length, b.length);
        for (let k = maxLen; k > 0; k--) {
            if (a.endsWith(b.slice(0, k))) return k;
        }
        return 0;
    };

    const o1 = getOverlap(s1, s2);
    const c1 = s1 + s2.slice(o1);

    const o2 = getOverlap(s2, s1);
    const c2 = s2 + s1.slice(o2);

    if (c1.length < c2.length) return c1;
    if (c2.length < c1.length) return c2;
    return c1 < c2 ? c1 : c2;
};
